INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (18, 10, 'theory', 'Quiz: microservices and the gateway');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 10, 0, 'When is a monolith preferable to microservices?', '["Never", "When the team and product are small: easier to develop, debug, and deploy", "Only for databases", "When there are many servers"]', 1, 'Microservices trade simplicity for independence; for small products the distribution tax is not justified.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 10, 1, 'Why should each microservice have its own database?', '["It is cheaper", "A shared database couples services in secret: a change to a table breaks everyone", "Databases can''t work together", "A protocol requires it"]', 1, 'Shared tables are the strongest coupling; there must be exactly one owner of the data.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 10, 2, 'What role does an API gateway play?', '["Stores data", "A single entry point: routing, authentication, limits, aggregation", "Replaces the database", "Encrypts disks"]', 1, 'The gateway hides the set of services from the client and takes over the common entry functions.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 10, 3, 'What counts as a compatible interface change?', '["Removing a field", "Adding an optional field", "Changing a field''s type", "Renaming a method"]', 1, 'Adding an optional field doesn''t break old clients; removal and changing the meaning do.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 10, 4, 'What replaces transactions that span several microservices?', '["One shared transaction", "Sagas and events with eventual consistency", "Locking all the databases", "Nothing: such operations are forbidden"]', 1, 'A chain of local steps with compensations; data is synchronized with events.');
